31		var result Definition
32		err = s.withLock(func() (bool, error) {
33			circuit := findCircuit(s.data.Circuits, name, version)
34			if circuit == nil {
35				return false, notFoundf("circuit %q version %d does not exist", name, version)
36			}
37			if circuit.Frozen {
38				return false, frozenf("circuit %q version %d is frozen; its constraint definition cannot be replaced", name, version)
39			}
40			parsed, perr := parseDefinitionJSON(raw, circuit.PublicInputs, circuit.PrivateInputs, circuit.Constraints)
41			if perr != nil {
42				return false, perr
43			}
44			persisted := parsed.toPersist()
45			circuit.Definition = &persisted
46			result = parsed.toExport()
47			return true, nil
48		})
49		return result, err
50	}
