52	// GetDefinition returns the imported definition of one version. A version
53	// without one yields ErrDefinitionMissing, and an unknown version
54	// ErrNotFound.
55	func (s *Store) GetDefinition(name string, version int) (Definition, error) {
56		if err := validateCircuitKey(name, version); err != nil {
57			return Definition{}, err
58		}
59		var result Definition
60		err := s.withLockRead(func() error {
61			circuit := findCircuit(s.data.Circuits, name, version)
62			if circuit == nil {
63				return notFoundf("circuit %q version %d does not exist", name, version)
64			}
65			if circuit.Definition == nil {
66				return definitionMissingf("circuit %q version %d has no constraint definition", name, version)
67			}
68			parsed, perr := definitionFromPersist(*circuit.Definition, circuit.PublicInputs, circuit.PrivateInputs)
69			if perr != nil {
