149	// CheckInput tests one input assignment against the named version's
150	// compiled artifact. hash must equal that artifact's hash, binding the check
151	// to an explicit compilation result.
152	//
153	// Gating errors are reported distinctly: unknown version ErrNotFound,
154	// unfrozen version ErrNotFrozen, no compiled artifact ErrArtifactMissing and
155	// a hash that does not belong to the target version ErrArtifactMismatch. A
156	// malformed witness (wrong lengths or illegal values; a nil slice stands for
157	// an empty one) yields ErrInvalidInput and never reaches evaluation.
158	//
159	// On success the verdict reports satisfaction, the bound artifact hash and,
160	// when unsatisfied, the 1-based index of the first failing constraint. No
161	// private input value is included in the result and no proof job is created.
162	//
163	// CheckInputFile applies exactly the same gating, binding and evaluation;
164	// only the witness representation differs.
165	func (s *Store) CheckInput(name string, version int, hash string, witness Witness) (CheckResult, error) {
166		if err := validateCheckRequest(name, version, hash); err != nil {
167			return CheckResult{}, err
168		}
169		var result CheckResult
170		err := s.withLockRead(func() error {
171			def, boundHash, gerr := s.boundCheckDefinition(name, version, hash)
172			if gerr != nil {
173				return gerr
174			}
175			if err := validateWitness(witness, def.public, def.private); err != nil {
176				return err
177			}
178			result = evaluateCheck(def, witness, boundHash)
179			return nil
180		})
181		return result, err
182	}
