184	// CheckInputFile is CheckInput with the witness read from a JSON file. It
185	// shares every gating, binding and evaluation rule with CheckInput; the only
186	// differences are how the witness is supplied (a strict JSON document that
187	// must explicitly contain both string arrays, even when empty) and that an
188	// unreadable or malformed file is reported as an input format error.
189	//
190	// The file is read first, so a missing or unreadable file keeps its read
191	// error; but once the file can be read, all binding gating still runs
192	// against the live store — an unknown version, a draft, a missing artifact
193	// or a wrong hash is reported before any complaint about the file's
194	// contents.
195	func (s *Store) CheckInputFile(name string, version int, hash, path string) (CheckResult, error) {
196		if err := validateCheckRequest(name, version, hash); err != nil {
197			return CheckResult{}, err
198		}
199		raw, err := os.ReadFile(path)
200		if err != nil {
201			return CheckResult{}, inputFormatf("cannot read input file %q: %v", path, err)
202		}
203		var result CheckResult
204		err = s.withLockRead(func() error {
205			def, boundHash, gerr := s.boundCheckDefinition(name, version, hash)
206			if gerr != nil {
207				return gerr
208			}
209			witness, werr := parseWitness(raw, def.public, def.private)
210			if werr != nil {
211				return werr
212			}
213			result = evaluateCheck(def, witness, boundHash)
214			return nil
215		})
216		return result, err
217	}
