219	// validateCheckRequest covers the request-shape checks common to both
220	// entry points: an explicit non-whitespace circuit key and a non-empty
221	// artifact hash.
222	func validateCheckRequest(name string, version int, hash string) error {
223		if err := validateCircuitKey(name, version); err != nil {
224			return err
225		}
226		if hash == "" {
227			return invalidf("an artifact hash is required to check inputs")
228		}
229		return nil
230	}
231	
232	// boundCheckDefinition resolves and verifies everything a check is bound
233	// to, in the required order: the version must exist and be frozen, its
234	// compiled artifact must exist, the supplied hash must equal that
235	// artifact's hash (artifacts of other names or versions never qualify), and
236	// the stored definition behind the artifact must be readable. It returns
237	// the canonical definition and the bound artifact hash.
238	//
239	// Callers must hold the store read lock.
240	func (s *Store) boundCheckDefinition(name string, version int, hash string) (*canonicalDefinition, string, error) {
241		circuit := findCircuit(s.data.Circuits, name, version)
242		if circuit == nil {
