10	// writeFile is a small helper for seeding JSON input files.
11	func writeFile(t *testing.T, dir, name, content string) string {
12		t.Helper()
13		path := filepath.Join(dir, name)
14		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
15			t.Fatal(err)
