22	
23	const cliGoodInput = `{"public":["2"],"private":["3"]}`
24	
25	// 100003 ≡ 1 mod 7, so 2·1 = 2 ≠ 6: this fails the one constraint. The
26	// distinctive value also lets the test assert the private input is never
27	// echoed in the verdict.
28	const cliBadInput = `{"public":["2"],"private":["100003"]}`
29	
30	func TestCLIConstraintLifecycle(t *testing.T) {
31		work := t.TempDir()
32		dir := filepath.Join(work, "bench")
33		defPath := writeFile(t, work, "def.json", cliDef)
34		goodPath := writeFile(t, work, "good.json", cliGoodInput)
35		badPath := writeFile(t, work, "bad.json", cliBadInput)
36	
37		type res struct {
38			code int
39			out  string
40			err  string
41		}
42		call := func(args ...string) res {
43			c, o, e := runCapture(t, args...)
44			return res{c, o, e}
45		}
46	
47		// Create a draft whose counts match the definition, then import.
48		if r := call("circuit-create", "--dir", dir, "--name", "mul", "--version", "1",
49			"--constraints", "1", "--public-inputs", "1", "--private-inputs", "1",
50			"--description", "smoke"); r.code != 0 {
51			t.Fatalf("create: %+v", r)
52		}
53		if r := call("constraint-import", "--dir", dir, "--name", "mul", "--version", "1",
54			"--file", defPath); r.code != 0 || !strings.Contains(r.out, "modulus=7") {
55			t.Fatalf("import: %+v", r)
56		}
57		// Compile is refused before freeze.
58		if r := call("circuit-compile", "--dir", dir, "--name", "mul", "--version", "1"); r.code != 1 || !strings.Contains(r.err, "not frozen") {
59			t.Fatalf("compile draft: %+v", r)
60		}
61		// Illegal JSON is a rule failure and leaves no definition.
62		badDef := writeFile(t, work, "bad.json2", `{"modulus":"9","constraints":[]}`)
63		if r := call("constraint-import", "--dir", dir, "--name", "mul", "--version", "1",
64			"--file", badDef); r.code != 1 || !strings.Contains(r.err, "prime") {
65			t.Fatalf("composite modulus: %+v", r)
66		}
67		// Freeze, then compile to a stable hash.
68		if r := call("circuit-freeze", "--dir", dir, "--name", "mul", "--version", "1"); r.code != 0 {
69			t.Fatalf("freeze: %+v", r)
70		}
71		r1 := call("circuit-compile", "--dir", dir, "--name", "mul", "--version", "1")
72		if r1.code != 0 || !strings.Contains(r1.out, "hash=") {
73			t.Fatalf("compile: %+v", r1)
74		}
75		hash := strings.TrimSpace(strings.SplitN(strings.SplitAfter(r1.out, "hash=")[1], "\n", 2)[0])
76		if len(hash) != 64 {
77			t.Fatalf("bad hash %q", hash)
78		}
79		// Recompiling returns the same artifact.
80		r2 := call("circuit-compile", "--dir", dir, "--name", "mul", "--version", "1")
81		if r2.code != 0 || !strings.Contains(r2.out, "hash="+hash) {
82			t.Fatalf("recompile differs: %+v", r2)
83		}
84		// A frozen definition cannot be replaced.
85		if r := call("constraint-import", "--dir", dir, "--name", "mul", "--version", "1",
86			"--file", defPath); r.code != 1 || !strings.Contains(r.err, "frozen") {
87			t.Fatalf("frozen replace: %+v", r)
88		}
89	
90		// Satisfied input.
91		if r := call("input-check", "--dir", dir, "--name", "mul", "--version", "1",
92			"--hash", hash, "--file", goodPath); r.code != 0 ||
93			!strings.Contains(r.out, "satisfied=true") || strings.Contains(r.out, "private") {
94			t.Fatalf("satisfied check: %+v", r)
95		}
96		// Unsatisfied input: verdict on stdout, exit 0, first failure reported,
97		// no private value echoed.
98		if r := call("input-check", "--dir", dir, "--name", "mul", "--version", "1",
99			"--hash", hash, "--file", badPath); r.code != 0 ||
100			!strings.Contains(r.out, "satisfied=false") || !strings.Contains(r.out, "first_failure=1") ||
101			strings.Contains(r.out, "100003") || strings.Contains(r.err, "100003") {
102			t.Fatalf("unsatisfied check: %+v", r)
103		}
104	
105		// Missing --hash / --file are usage errors.
106		if r := call("input-check", "--dir", dir, "--name", "mul", "--version", "1",
107			"--file", goodPath); r.code != 2 {
108			t.Fatalf("missing hash: %+v", r)
109		}
110		if r := call("input-check", "--dir", dir, "--name", "mul", "--version", "1",
111			"--hash", hash); r.code != 2 {
112			t.Fatalf("missing file: %+v", r)
113		}
114		// Wrong hash -> artifact mismatch (exit 1).
115		if r := call("input-check", "--dir", dir, "--name", "mul", "--version", "1",
116			"--hash", strings.Repeat("0", 64), "--file", goodPath); r.code != 1 ||
117			!strings.Contains(r.err, "artifact mismatch") {
